package ro.whistlab.core;
import java.util.*;import org.junit.Test;import com.fasterxml.jackson.databind.*;import ro.whistlab.coach.*;import ro.whistlab.coach.baseline.RoundEightIndependentPlayer;import ro.whistlab.core.baseline.RoundTenMonteCarloAi;
public class CertifiedContractRegressionTest {
 private static final ObjectMapper JSON=new ObjectMapper();
 private JsonNode fixture(String key)throws Exception{return JSON.readTree(getClass().getResourceAsStream("/regressions/contract-certificate/cases.json")).path(key);}
 private MonteCarloAi.View view(JsonNode f)throws Exception{return JSON.treeToValue(f.path("input").path("before"),MonteCarloAi.View.class);}
 @Test public void anObservedRiskyDiscardMustYieldToAUniversallyCertainContract()throws Exception{var f=fixture("positive");var v=view(f);var oracle=PublicEndgameOracle.audit(v);var context=new LinkedHashMap<String,Object>();context.put("purpose","Keep the contract already made: discard10D, retainQH");context.put("rule","Bid1 and one trick already won. BothQH/10Dare legal discards on the spade lead without clubs. Across all96compatible deals and every legal continuation, discarding10D preserves exactly1trick; discardingQH can force an unwanted second trick.");context.put("origin",f.path("input").path("gameId").asText());context.put("before",f.path("input").path("before"));context.put("independentOracle",Map.of("worlds",oracle.worlds(),"safe",oracle.safe(),"allPossibleFinalTricksByChoice",oracle.finalWon(),"unsafeWitness",oracle.witness()));context.put("scope","Universal legal-play certificate from own/public facts; no real hidden opponent cards or opponent-policy assumption.");
 CapturedRegression.run("certified-contract-observed-regression",getClass().getName(),"anObservedRiskyDiscardMustYieldToAUniversallyCertainContract",context,c->{c.equal("Independent feasible world count",96,oracle.worlds());c.equal("Literal uniquely safe discard",List.of("10D"),oracle.safe());c.equal("Old frozenV8 reproduces the observed riskyQH", "QH",PublicEndgameOracle.code(RoundEightIndependentPlayer.card(AcceptedBaselineViews.player(v)).value()));c.equal("RiskyQH admits both exact and missed contracts",Set.of(1,2),oracle.finalWon().get("QH"));c.equal("10D always keeps exactlyone",Set.of(1),oracle.finalWon().get("10D"));c.equal("New Independent takes the certain contract","10D",PublicEndgameOracle.code(IndependentPlayer.card(LostGameContractRegressionTest.independent(v)).value()));c.equal("Expert also takes the certain contract","10D",LossMiningTest.code(MonteCarloAi.chooseCard(v).card()));var core=ContractGuarantee.choose(v,LossMiningTest.card("QH"));var independent=WorldEnumerationProbe.certificate(LostGameContractRegressionTest.independent(v),PublicEndgameOracle.id(LossMiningTest.card("QH")),40000);c.equal("Core guard corrects a risky model proposal","10D",LossMiningTest.code(core.card()));c.equal("Independent guard corrects a risky model proposal","10D",PublicEndgameOracle.code(independent.card()));c.equal("Both independent proof implementations certify",true,core.certified()&&independent.certified());context.put("runtimeCertificates",Map.of("core",core,"independent",independent));});}
 @Test public void noCertificateMeansTheAcceptedFallbackIsPreserved()throws Exception{var f=fixture("negative");var v=view(f);var oracle=PublicEndgameOracle.audit(v);var p=LostGameContractRegressionTest.independent(v);CapturedRegression.run("certified-contract-no-guarantee-fallback",getClass().getName(),"noCertificateMeansTheAcceptedFallbackIsPreserved",Map.of("purpose","Do not replace a proven player with an unproven heuristic","rule","NeitherJHnorJCguarantees zero across all legal continuations. The guard must preserve the existing planner, even if one sampled model looks better.","before",v,"independentOracle",Map.of("worlds",oracle.worlds(),"safe",oracle.safe(),"finalWon",oracle.finalWon())),c->{c.equal("No universally safe alternative exists",List.of(),oracle.safe());c.equal("Independent fallback retains the frozenV8decision",RoundEightIndependentPlayer.card(AcceptedBaselineViews.player(v)).value(),IndependentPlayer.card(p).value());c.equal("Expert fallback retains frozenSafety10",RoundTenMonteCarloAi.chooseCard(AcceptedBaselineViews.expert(v)).card(),MonteCarloAi.chooseCard(v).card());c.equal("Core does not invent a certificate",false,ContractGuarantee.choose(v,LossMiningTest.card("JC")).certified());c.equal("Independent does not invent a certificate",false,WorldEnumerationProbe.certificate(p,PublicEndgameOracle.id(LossMiningTest.card("JC")),40000).certified());});}
 @Test public void anImpossibleContractDoesNotTriggerARescueOverride()throws Exception{var f=fixture("impossible");var v=view(f);var p=LostGameContractRegressionTest.independent(v);CapturedRegression.run("certified-contract-impossible-fallback",getClass().getName(),"anImpossibleContractDoesNotTriggerARescueOverride",Map.of("purpose","Separate irrecoverable misses from avoidable risk","rule","Bid4, one trick won, onlytwo own cards remain. Four tricks cannot be reached; preserve the accepted penalty-minimizing planner.","before",v),c->{c.equal("Independent preserves its frozen fallback",RoundEightIndependentPlayer.card(AcceptedBaselineViews.player(v)).value(),IndependentPlayer.card(p).value());c.equal("Expert preserves its frozen fallback",RoundTenMonteCarloAi.chooseCard(AcceptedBaselineViews.expert(v)).card(),MonteCarloAi.chooseCard(v).card());c.equal("No false rescue certificate",false,ContractGuarantee.choose(v,LossMiningTest.card("AD")).certified());});}
 @Test public void anExhaustedProofCannotBeReportedAsCertain()throws Exception{var v=view(fixture("positive"));int q=PublicEndgameOracle.id(LossMiningTest.card("QH"));var a=ContractGuarantee.choose(v,LossMiningTest.card("QH"),1);var b=WorldEnumerationProbe.certificate(LostGameContractRegressionTest.independent(v),q,1);CapturedRegression.run("certified-contract-budget-unknown",getClass().getName(),"anExhaustedProofCannotBeReportedAsCertain",Map.of("purpose","Do not convert a partial search into100%confidence","rule","A deliberatelyone-node proof budget cannot evaluate all96deals/continuations. Return the original proposal with certified=false; no sampled or partial proof is accepted.","before",v,"nodeBudget",1),c->{c.equal("Core incomplete proof is not certified",false,a.certified());c.equal("Independent incomplete proof is not certified",false,b.certified());c.equal("Core proposal remains unchanged","QH",LossMiningTest.code(a.card()));c.equal("Independent proposal remains unchanged",q,b.card());});}
}
